import 'package:flutter/material.dart';
import '../workshop_customers.dart';

/// Reusable view only. The aggregate must durably save the active event and
/// shuffled stable IDs before opening this panel, pause simulation, and commit
/// the response/affinity/follow-up atomically before closing or showing reaction.
/// No reward, timer, inventory, or random draw is generated by this widget.
class CustomerChoicePanel extends StatefulWidget {
  final WorkshopCustomerCatalog catalog;
  final String eventId;
  final Set<String> completedStories;
  final List<String> choiceOrder;
  final String? selected;
  final Future<bool> Function(String selection) onSelect;
  final Future<bool> Function() onCloseReaction;
  const CustomerChoicePanel({super.key, required this.catalog,
    required this.eventId, required this.completedStories,
    required this.choiceOrder, required this.onSelect,
    required this.onCloseReaction, this.selected});
  @override
  State<CustomerChoicePanel> createState() => _CustomerChoicePanelState();
}
class _CustomerChoicePanelState extends State<CustomerChoicePanel> {
  bool _saving = false;
  String? _error;
  Future<void> _submit(Future<bool> Function() action) async {
    if (_saving) return;
    setState(() { _saving = true; _error = null; });
    try {
      final committed = await action();
      if (mounted && !committed) setState(() { _error = '저장되지 않았어요. 확인 후 다시 시도해 주세요.'; });
    } catch (_) {
      if (mounted) setState(() { _error = '저장을 확인한 뒤 다시 시도해 주세요.'; });
    } finally { if (mounted) setState(() { _saving = false; }); }
  }
  @override
  Widget build(BuildContext context) {
    final ids = widget.choiceOrder;
    if (ids.length != 3 || ids.toSet().length != 3 || !ids.toSet().containsAll(['a','b','c'])) {
      return const Text('선택 순서를 확인해야 해요.');
    }
    final event = widget.catalog.choice(widget.eventId), npc = event['npc_id'] as String;
    final choices = {for (final row in (event['choices'] as List).cast<Map<String,dynamic>>()) row['id'] as String: row};
    final selected = widget.selected;
    if (selected != null && !['a','b','c'].contains(selected)) return const Text('선택 기록을 확인해야 해요.');
    return Semantics(container:true, child:Column(mainAxisSize:MainAxisSize.min,
      crossAxisAlignment:CrossAxisAlignment.stretch, children:[
      Text(widget.catalog.displayName(npc,widget.completedStories), style:Theme.of(context).textTheme.titleMedium),
      Text(selected == null ? event['prompt'] as String : choices[selected]!['response'] as String),
      if (selected == null) ...[
        for (final id in ids) Padding(padding:const EdgeInsets.symmetric(vertical:4),child:
          OutlinedButton(onPressed:_saving ? null : () => _submit(() => widget.onSelect(id)),
            child:Text(choices[id]!['text'] as String))),
        TextButton(onPressed:_saving ? null : () => _submit(() => widget.onSelect('wave')),
          child:Text(choices['wave']!['text'] as String)),
      ] else FilledButton(onPressed:_saving ? null : () => _submit(widget.onCloseReaction),child:const Text('대화 마치기')),
      if (_saving) const Text('저장 확인 중이에요.'),
      if (_error != null) Text(_error!,semanticsLabel:_error),
    ]));
  }
}

/// Only a met NPC is visible; secret preferences and reference full names are
/// intentionally absent. Caller supplies facts already revealed by play.
class CustomerRecordCard extends StatelessWidget {
  final WorkshopCustomerCatalog catalog;
  final String npcId;
  final bool met;
  final Set<String> completedStories;
  final String stageLabel;
  final List<String> observedPreferences, revealedStories;
  const CustomerRecordCard({super.key, required this.catalog,required this.npcId,
    required this.met, required this.completedStories,required this.stageLabel,
    this.observedPreferences=const [],this.revealedStories=const []});
  @override
  Widget build(BuildContext context) {
    if (!met) return const ListTile(title:Text('아직 만나지 않은 이웃'));
    final npc=catalog.npc(npcId);
    return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(
      crossAxisAlignment:CrossAxisAlignment.start,children:[
      Text(catalog.displayName(npcId,completedStories),style:Theme.of(context).textTheme.titleMedium),
      Text(npc['appearance'] as String),Text(stageLabel),
      for(final preference in observedPreferences) Text(preference),
      for(final story in revealedStories) Text(story),
    ])));
  }
}
